function update(dt){if(state!=="playing")return;elapsed+=dt;if(messageTimer>0&&(messageTimer-=dt)<=0)ui.message.classList.remove("show");screenShake=Math.max(0,screenShake-dt*28);flash=Math.max(0,flash-dt*3);player.invuln=Math.max(0,player.invuln-dt);player.dodgeCooldown=Math.max(0,player.dodgeCooldown-dt);player.speedBuff=Math.max(0,player.speedBuff-dt);player.metrics.noHit+=dt;player.metrics.maxNoHit=Math.max(player.metrics.maxNoHit,player.metrics.noHit);if(player.hp/player.maxHp<.35)player.metrics.lowHpTime+=dt;updateInput();if(Math.hypot(move.x,move.y)>.08){player.facing=Math.atan2(move.y,move.x);player.moving=true}else player.moving=false;if(player.dodgeTimer>0){player.dodgeTimer-=dt;player.x+=player.dodgeVx*dt;player.y+=player.dodgeVy*dt}else{const sm=player.speedBuff>0?1.2+.06*player.cloudStep:1;player.x+=move.x*player.speed*sm*dt;player.y+=move.y*player.speed*sm*dt;}player.regenTimer-=dt;if(player.regen&&player.regenTimer<=0){player.regenTimer=8;player.hp=Math.min(player.maxHp,player.hp+player.regen)}player.fireTimer-=dt;if(player.fireTimer<=0){fireBasic();player.fireTimer*=player.attackSpeedMul}tickArts(dt);spawnTimer-=dt;const diff=difficultyDefs[selectedDifficulty],target=Math.min(diff.maxEnemies,(20+elapsed*1.02)*diff.spawn);if(spawnTimer<=0&&enemies.length<target){spawnTimer=Math.max(.065,(.48-elapsed*.0022)/diff.spawn);const r=Math.random();let type="bandit";if(elapsed>90&&r<.12)type="assassin";else if(elapsed>58&&r<.27)type="master";else if(elapsed>35&&r<.43)type="brute";else if(elapsed>12&&r<.65)type="spear";spawnAround(type)}while(elapsed>=nextMiniBossAt&&nextMiniBossAt<finalBossAt){spawnMiniBoss();nextMiniBossAt+=60}if(!bossSpawned&&elapsed>=finalBossAt)spawnBoss();updateSpecialPatterns(dt);updateProjectiles(dt);updateEnemies(dt);updateGems(dt);updateChests(dt);updateHazards(dt);updateFields(dt);updateDelayed(dt);updateParticles(dt);updateVisuals(dt);enemies=enemies.filter(e=>!e.dead);projectiles=projectiles.filter(p=>p.life>0&&p.hits<=p.pierce);gems=gems.filter(g=>!g.dead);chests=chests.filter(c=>!c.dead);hazards=hazards.filter(h=>!h.dead);particles=particles.filter(p=>p.life>0);visuals=visuals.filter(v=>v.life>0);fields=fields.filter(f=>f.life>0);delayed=delayed.filter(d=>d.time>0);checkHidden();updateHud();if(elapsed>=runDuration&&state==="playing"&&boss)endGame(false,"time")}
