 e.summon-=dt;e.blast-=dt;if(e.dash)e.dash-=dt;if(e.orbs)e.orbs-=dt;if(e.cross)e.cross-=dt;if(e.puddle)e.puddle-=dt;
 if(e.summon<=0){e.summon=d.summon*(e.phase3?.78:e.phase2?.85:1);const n=5+d.rank*2+(e.phase3?2:0);for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2;spawnEnemy(i%2?"assassin":"spear",e.x+Math.cos(a)*82,e.y+Math.sin(a)*82)}showMessage("혈마 · 혈교 사도 소환",1)}
 if(e.blast<=0){e.blast=d.blast*(e.phase3?.72:e.phase2?.82:1);const baseR=94+d.rank*14;hazards.push({type:"blast",x:player.x,y:player.y,r:baseR,time:.82,damage:e.damage,color:"#b6323a",dead:false});if(d.rank>=2){const ang=Math.random()*Math.PI*2;hazards.push({type:"blast",x:player.x+Math.cos(ang)*92,y:player.y+Math.sin(ang)*92,r:baseR*.72,time:.72,damage:e.damage*.92,color:"#cc454d",dead:false});hazards.push({type:"blast",x:player.x-Math.cos(ang)*92,y:player.y-Math.sin(ang)*92,r:baseR*.72,time:.72,damage:e.damage*.92,color:"#cc454d",dead:false})}showMessage("혈마 · 혈폭장",.8)}
 if(d.dash>0&&e.dash<=0){e.dash=d.dash*(e.phase3?.72:e.phase2?.85:1);prepareCharge(e,e.phase3?880:780,e.damage*(e.phase3?1.28:1.16));showMessage(e.phase3?"혈마 · 혈영연진":"혈마 · 혈영신법",.9)}
