function prepareCharge(e,speed,damage){const a=Math.atan2(player.y-e.y,player.x-e.x);e.chargeDelay=.44;e.chargeTime=.62;e.chargeVx=Math.cos(a)*speed;e.chargeVy=Math.sin(a)*speed;e.chargeDamage=damage||e.damage;addVisual({type:"line",x1:e.x,y1:e.y,x2:e.x+Math.cos(a)*500,y2:e.y+Math.sin(a)*500,width:4,life:.44,max:.44,color:"#d35a5a"})}
function updateProjectiles(dt){for(const p of projectiles){if(p.homing){const t=nearest(260,p.x,p.y);if(t){const sp=Math.hypot(p.vx,p.vy),ta=Math.atan2(t.y-p.y,t.x-p.x),ca=Math.atan2(p.vy,p.vx),da=Math.atan2(Math.sin(ta-ca),Math.cos(ta-ca)),na=ca+da*Math.min(1,p.homing*dt);p.vx=Math.cos(na)*sp;p.vy=Math.sin(na)*sp}}p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.trail&&Math.random()<.55)particle(p.x,p.y,p.color,20,1);for(const e of enemies){if(e.dead||p.hits>p.pierce)break;const rr=e.r+p.r;if((e.x-p.x)**2+(e.y-p.y)**2<rr*rr){damageEnemy(e,p.damage,p.source,{poison:p.poison,poisonTime:p.poisonTime,knock:p.knock,elemental:p.elemental,color:p.color,slow:player.forgedWeapon&&player.forgedWeapon.ability==="ice"?.84:0,slowTime:1.3,distance:Math.hypot(e.x-player.x,e.y-player.y)});if(player.forgedWeapon&&player.forgedWeapon.ability==="fire"&&Math.random()<.08)aoe(p.x,p.y,34,Math.max(4,p.damage*.32),"forgefire",{color:"#ef8052",elemental:true,shake:2});if(player.forgedWeapon&&player.forgedWeapon.ability==="thunder"&&Math.random()<.08){const z=nearest(125,e.x,e.y,[e]);if(z){addVisual({type:"lightning",x1:e.x,y1:e.y,x2:z.x,y2:z.y,width:2,life:.13,max:.13,color:"#8bd5ff"});damageEnemy(z,p.damage*.28,"forgethunder",{elemental:true,color:"#8bd5ff"})}}if(p.shape==="spear"&&p.hits>0)player.metrics.pierceHits++;if(p.knock){const d=Math.hypot(e.x-p.x,e.y-p.y)||1;e.pushX+=(e.x-p.x)/d*p.knock;e.pushY+=(e.y-p.y)/d*p.knock;player.metrics.knockbacks++}p.hits++;if(p.explode){aoe(p.x,p.y,p.explode,p.damage*.72,p.source,{elemental:p.elemental,color:p.color,shake:5});p.hits=p.pierce+1}}}}}
function updateEnemies(dt){for(const e of enemies){if(e.dead)continue;e.hit=Math.max(0,e.hit-dt);e.orbitHit=Math.max(0,e.orbitHit-dt);if(e.poisonTime>0){e.poisonTime-=dt;e.poisonTick-=dt;if(e.poisonTick<=0){e.poisonTick=.55;damageEnemy(e,e.poison*.55,"poison",{color:C.poison})}}if(e.slowTime>0)e.slowTime-=dt;else e.slow=1;const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(e.chargeDelay>0){e.chargeDelay-=dt}else if(e.chargeTime>0){e.chargeTime-=dt;e.x+=e.chargeVx*dt;e.y+=e.chargeVy*dt}else{const sp=e.speed*e.slow*(e.type==="boss"&&d<130?.55:1);e.x+=(dx/d*sp+e.pushX)*dt;e.y+=(dy/d*sp+e.pushY)*dt}e.pushX*=Math.pow(.025,dt);e.pushY*=Math.pow(.025,dt);if(d<player.r+e.r&&player.invuln<=0)hurtPlayer(e.chargeTime>0?(e.chargeDamage||e.damage):e.damage)}}
function updateGems(dt){for(const g of gems){const dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;if(d<player.pickup*2.2){const pull=190+(player.pickup*2.2-d)*4;g.vx+=dx/d*pull*dt;g.vy+=dy/d*pull*dt}g.vx*=Math.pow(.12,dt);g.vy*=Math.pow(.12,dt);g.x+=g.vx*dt;g.y+=g.vy*dt;if(d<player.r+g.r+5){g.dead=true;if(g.kind==="heal"||g.heal){player.hp=Math.min(player.maxHp,player.hp+(g.heal||15));showMessage("영약을 복용했다",.9)}else if(g.kind==="gold"){account.gold+=g.value;player.runGold+=g.value}else if(g.kind==="ore"){const k=oreKey(g.type,g.grade);account.ores[k]=(account.ores[k]||0)+1;player.runOres[k]=(player.runOres[k]||0)+1;showMessage(`${gradeName(g.grade)} ${oreTypes[g.type].name} 획득`,1.1)}else gainXp(g.value);refreshAccountUI();beep(g.kind==="ore"?690:500,.025,.018,g.kind==="ore"?"triangle":"sine")}}}

function updateChests(dt){if(state!=="playing")return;for(const c of chests){c.bob+=dt*3;const d=Math.hypot(player.x-c.x,player.y-c.y);if(d<player.r+c.r+8){c.dead=true;player.chestsOpened++;openAugmentChoice();break}}}
function updateHazards(dt){for(const h of hazards){if(h.dead)continue;if(h.type==="blast"){h.time-=dt;if(h.time<=0){if(Math.hypot(player.x-h.x,player.y-h.y)<h.r+player.r)hurtPlayer(h.damage);addVisual({type:"ring",x:h.x,y:h.y,r:h.r,life:.35,max:.35,color:h.color||"#b6323a",width:7});particle(h.x,h.y,h.color||"#b6323a",120,12);h.dead=true}}else if(h.type==="orb"){if(h.homing){const ta=Math.atan2(player.y-h.y,player.x-h.x),ca=Math.atan2(h.vy,h.vx),sp=Math.hypot(h.vx,h.vy)||1,da=Math.atan2(Math.sin(ta-ca),Math.cos(ta-ca));const na=ca+da*Math.min(1,h.homing*dt);h.vx=Math.cos(na)*sp;h.vy=Math.sin(na)*sp}h.x+=h.vx*dt;h.y+=h.vy*dt;h.life-=dt;if(Math.hypot(player.x-h.x,player.y-h.y)<player.r+h.r){hurtPlayer(h.damage);h.dead=true}else if(h.life<=0)h.dead=true}else if(h.type==="puddle"){h.life-=dt;h.tick-=dt;if(h.tick<=0){h.tick=.32;if(Math.hypot(player.x-h.x,player.y-h.y)<h.r+player.r)hurtPlayer(h.damage)}}else if(h.type==="cross"){h.time-=dt;if(h.time<=0){const w=h.w||38;if(Math.abs(player.x-h.x)<w+player.r||Math.abs(player.y-h.y)<w+player.r)hurtPlayer(h.damage);addVisual({type:"line",x1:h.x-900,y1:h.y,x2:h.x+900,y2:h.y,width:w*1.2,life:.18,max:.18,color:h.color||"#df5a63"});addVisual({type:"line",x1:h.x,y1:h.y-900,x2:h.x,y2:h.y+900,width:w*1.2,life:.18,max:.18,color:h.color||"#df5a63"});h.dead=true}}}}
function updateFields(dt){for(const f of fields){f.life-=dt;f.tick-=dt;if(f.tick<=0){f.tick=.55;for(const e of enemies){if(e.dead)continue;if(Math.hypot(e.x-f.x,e.y-f.y)<f.r+e.r)damageEnemy(e,f.damage,"poison",{poison:f.damage*.8,poisonTime:2.5,color:f.color})}}}}
function updateDelayed(dt){for(const d of delayed){d.time-=dt;if(d.time<=0){if(d.type==="strike")aoe(d.x,d.y,d.r,d.damage,d.source,{color:d.color,knock:d.knock||0,shake:5});else if(d.type==="aoe")aoe(d.x,d.y,d.r,d.damage,d.source,{color:d.color,knock:d.knock||0,shake:4});else if(d.type==="katanaSlash"){const px=player.x+Math.cos(d.a+Math.PI/2)*d.side,py=player.y+Math.sin(d.a+Math.PI/2)*d.side,x2=px+Math.cos(d.a)*d.len,y2=py+Math.sin(d.a)*d.len;lineHit(px,py,x2,y2,d.width,d.damage,"basic",{shake:3+d.index*.55,color:d.color,life:.15});addVisual({type:"slashArc",x:px+Math.cos(d.a)*(40+d.index*4),y:py+Math.sin(d.a)*(40+d.index*4),a:d.a,r:d.arc,life:.18,max:.18,color:d.color,width:d.arcWidth});addVisual({type:"afterimage",x:player.x-Math.cos(d.a)*(5+d.index*2),y:player.y-Math.sin(d.a)*(5+d.index*2),r:16+d.index,life:.13,max:.13,color:d.color});beep(330+d.index*32,.028,.022,d.index===d.total-1?"sawtooth":"square")}}}}
function updateParticles(dt){for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}}
function updateVisuals(dt){for(const v of visuals)v.life-=dt}
function updateHud(){ui.hpFill.style.width=Math.max(0,player.hp/player.maxHp*100)+"%";ui.xpFill.style.width=Math.max(0,player.xp/player.xpNeed*100)+"%";ui.levelText.textContent="경지 "+player.level;ui.timeText.textContent=fmtTime(runDuration-elapsed);ui.killText.textContent="격파 "+player.kills;ui.goldHud.textContent=`금자 ${Math.floor(account.gold||0)}`;ui.oreHud.textContent=`광석 ${totalOres()}`;const cd=Math.max(0,player.dodgeCooldown);ui.dodgeHud.textContent=cd>0?`보법 ${cd.toFixed(1)}초`:"보법 준비";ui.dodgeCd.textContent=cd>0?cd.toFixed(1)+"초":"준비";ui.dodgeBtn.classList.toggle("cooling",cd>0);if(boss&&!boss.dead){ui.bossFill.style.width=Math.max(0,boss.hp/boss.maxHp*100)+"%";ui.bossText.textContent=Math.ceil(boss.hp)+" / "+Math.ceil(boss.maxHp)}}

