function drawEnemies(){for(const e of enemies){if(e.dead)continue;const s=ws(e.x,e.y);if(s.x<-80||s.x>W+80||s.y<-80||s.y>H+80)continue;ctx.save();ctx.translate(s.x,s.y);ctx.fillStyle=e.hit>0?"#f3ead0":e.color;ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();if(e.poisonTime>0){ctx.strokeStyle="rgba(174,110,194,.8)";ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,e.r+4,0,Math.PI*2);ctx.stroke()}if(e.type==="spear"){ctx.strokeStyle="#c4b892";ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-18,17);ctx.lineTo(18,-17);ctx.stroke()}else if(e.type==="brute"){ctx.strokeStyle="#2a211f";ctx.lineWidth=4;ctx.stroke()}else if(e.type==="master"||e.type==="assassin"){ctx.strokeStyle="#b7a4c9";ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,e.r+5,0,Math.PI*2);ctx.stroke()}else if(e.type==="midboss"){ctx.strokeStyle="#d9b95f";ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,e.r+5+Math.sin(elapsed*5)*2,0,Math.PI*2);ctx.stroke();ctx.fillStyle="#e8d79c";ctx.font="11px -apple-system,sans-serif";ctx.textAlign="center";ctx.fillText(e.bossName,0,-e.r-16)}else if(e.type==="boss"){ctx.strokeStyle="#d9b95f";ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,e.r+8+Math.sin(elapsed*4)*3,0,Math.PI*2);ctx.stroke()}if(e.type==="boss"||e.type==="midboss"||e.hp<e.maxHp){const bw=Math.max(25,e.r*2.1);ctx.fillStyle="rgba(0,0,0,.5)";ctx.fillRect(-bw/2,-e.r-11,bw,4);ctx.fillStyle=e.type==="boss"?"#b8473e":e.type==="midboss"?"#d98f4b":"#d9b95f";ctx.fillRect(-bw/2,-e.r-11,bw*Math.max(0,e.hp/e.maxHp),4)}ctx.restore()}}
function drawProjectiles(){for(const p of projectiles){const s=ws(p.x,p.y),a=Math.atan2(p.vy,p.vx);ctx.save();ctx.translate(s.x,s.y);ctx.rotate(a);ctx.fillStyle=p.color;if(p.shape==="arrow"){ctx.fillRect(-10,-1.5,18,3);ctx.beginPath();ctx.moveTo(10,0);ctx.lineTo(4,-5);ctx.lineTo(4,5);ctx.fill()}else if(p.shape==="spear"){ctx.fillRect(-15,-2.5,26,5);ctx.beginPath();ctx.moveTo(16,0);ctx.lineTo(7,-7);ctx.lineTo(7,7);ctx.fill()}else if(p.shape==="crescent"){const rr=Math.max(12,p.r*2.15);ctx.strokeStyle=p.color;ctx.lineWidth=Math.max(4,p.r*.72);ctx.beginPath();ctx.arc(0,0,rr,-1.12,1.12);ctx.stroke();ctx.globalAlpha=.35;ctx.lineWidth=Math.max(2,p.r*.34);ctx.beginPath();ctx.arc(-3,0,rr*.68,-1.05,1.05);ctx.stroke();ctx.globalAlpha=1}else if(p.shape==="needle"){ctx.fillRect(-8,-1,16,2)}else if(p.shape==="sword"){const z=Math.max(1,p.r/5);ctx.shadowColor=p.color;ctx.shadowBlur=7+z*2;ctx.fillRect(-15*z,-2*z,24*z,4*z);ctx.beginPath();ctx.moveTo(16*z,0);ctx.lineTo(7*z,-6*z);ctx.lineTo(7*z,6*z);ctx.closePath();ctx.fill();ctx.fillStyle="rgba(255,255,255,.75)";ctx.fillRect(-13*z,-.7*z,20*z,1.4*z)}else if(p.shape==="fire"||p.shape==="sun"||p.shape==="moon"){ctx.beginPath();ctx.arc(0,0,p.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle="rgba(255,255,255,.6)";ctx.stroke()}else if(p.shape==="fist"){ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(0,0,p.r,0,Math.PI*2);ctx.fill()}else{ctx.fillRect(-8,-2,16,4)}ctx.restore()}}
function drawGems(){for(const g of gems){if(g.dead)continue;const s=ws(g.x,g.y);if(g.kind==="gold"){ctx.fillStyle="#e6c457";ctx.beginPath();ctx.arc(s.x,s.y,g.r,0,Math.PI*2);ctx.fill();ctx.fillStyle="#6e5120";ctx.fillRect(s.x-1,s.y-4,2,8)}else if(g.kind==="ore"){const gd=gradeDefs.find(x=>x.id===g.grade)||gradeDefs[0];ctx.fillStyle=gd.color;ctx.beginPath();ctx.moveTo(s.x,s.y-g.r);ctx.lineTo(s.x+g.r*.8,s.y-g.r*.2);ctx.lineTo(s.x+g.r*.55,s.y+g.r);ctx.lineTo(s.x-g.r*.65,s.y+g.r*.55);ctx.lineTo(s.x-g.r,s.y-g.r*.25);ctx.closePath();ctx.fill();ctx.strokeStyle="#fff8";ctx.stroke()}else{ctx.fillStyle=g.heal||g.kind==="heal"?"#76b887":"#c9aa50";ctx.beginPath();ctx.moveTo(s.x,s.y-g.r);ctx.lineTo(s.x+g.r,s.y);ctx.lineTo(s.x,s.y+g.r);ctx.lineTo(s.x-g.r,s.y);ctx.closePath();ctx.fill()}}}

function drawChests(){for(const c of chests){if(c.dead)continue;const s=ws(c.x,c.y),y=s.y+Math.sin(c.bob)*4;ctx.save();ctx.translate(s.x,y);ctx.fillStyle="#c79d3d";ctx.fillRect(-12,-9,24,18);ctx.fillStyle="#f1d98c";ctx.fillRect(-2,-9,4,18);ctx.strokeStyle="#6e5120";ctx.lineWidth=2;ctx.strokeRect(-12,-9,24,18);ctx.restore()}}
function drawHazards(){for(const h of hazards){if(h.dead)continue;if(h.type==="blast"){const s=ws(h.x,h.y),pulse=.55+.25*Math.sin(performance.now()*.02);ctx.fillStyle=`rgba(178,42,52,${.12+pulse*.08})`;ctx.strokeStyle=h.color||"#b6323a";ctx.lineWidth=3;ctx.beginPath();ctx.arc(s.x,s.y,h.r,0,Math.PI*2);ctx.fill();ctx.stroke()}else if(h.type==="orb"){const s=ws(h.x,h.y);ctx.fillStyle=h.color||"#c23b46";ctx.beginPath();ctx.arc(s.x,s.y,h.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle="#f0a0a6";ctx.stroke()}}}
function drawFields(){for(const f of fields){const s=ws(f.x,f.y);ctx.fillStyle="rgba(160,92,180,"+Math.min(.22,f.life*.05)+")";ctx.beginPath();ctx.arc(s.x,s.y,f.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle="rgba(190,120,205,.4)";ctx.stroke()}}
function drawParticles(){for(const p of particles){const s=ws(p.x,p.y);ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(s.x-2,s.y-2,4,4)}ctx.globalAlpha=1}
function drawVisuals(){for(const v of visuals){const alpha=Math.max(0,v.life/v.max),col=v.color||"#fff";ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=v.width||4;if(v.type==="line"||v.type==="lightning"){const a=ws(v.x1,v.y1),b=ws(v.x2,v.y2);ctx.beginPath();ctx.moveTo(a.x,a.y);if(v.type==="lightning"){for(let i=1;i<7;i++){const t=i/7;ctx.lineTo(a.x+(b.x-a.x)*t+(Math.random()-.5)*14,a.y+(b.y-a.y)*t+(Math.random()-.5)*14)}}ctx.lineTo(b.x,b.y);ctx.stroke()}else if(v.type==="ring"||v.type==="marker"){const s=ws(v.x,v.y);ctx.beginPath();ctx.arc(s.x,s.y,v.r*(1.12-alpha*.12),0,Math.PI*2);ctx.stroke()}else if(v.type==="spiral"){const s=ws(v.x,v.y);ctx.beginPath();for(let i=0;i<36;i++){const t=i/35*Math.PI*2*1.5,r=v.r*i/35;const x=s.x+Math.cos(t+elapsed*4)*r,y=s.y+Math.sin(t+elapsed*4)*r;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}else if(v.type==="cone"){const s=ws(v.x,v.y);ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.arc(s.x,s.y,v.r,v.a-v.half,v.a+v.half);ctx.closePath();ctx.fillStyle=col;ctx.globalAlpha=alpha*.18;ctx.fill();ctx.globalAlpha=alpha;ctx.stroke()}else if(v.type==="cross"){const s=ws(v.x,v.y);ctx.translate(s.x,s.y);ctx.rotate(elapsed*2);for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);ctx.beginPath();ctx.moveTo(15,0);ctx.lineTo(v.r,0);ctx.stroke()}}else if(v.type==="yin"){const s=ws(v.x,v.y);ctx.beginPath();ctx.arc(s.x,s.y,v.r,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(s.x-v.r/4,s.y,v.r/4,0,Math.PI*2);ctx.arc(s.x+v.r/4,s.y,v.r/4,0,Math.PI*2);ctx.stroke()}else if(v.type==="afterimage"){const s=ws(v.x,v.y);ctx.globalAlpha=alpha*.45;ctx.beginPath();ctx.arc(s.x,s.y,v.r,0,Math.PI*2);ctx.fill()}else if(v.type==="dragon"){const s=ws(v.x,v.y);ctx.translate(s.x,s.y);ctx.rotate(v.a);ctx.beginPath();for(let i=0;i<18;i++){const x=i*24,y=Math.sin(i*.8+elapsed*10)*13;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.strokeStyle=col;ctx.lineWidth=10*alpha+2;ctx.stroke()}else if(v.type==="cloud"){const s=ws(v.x,v.y);for(let i=0;i<9;i++){const a=i*Math.PI*2/9+elapsed,r=v.r*(.25+(i%3)*.18);ctx.beginPath();ctx.arc(s.x+Math.cos(a)*r,s.y+Math.sin(a)*r,v.r*.25,0,Math.PI*2);ctx.fillStyle=col;ctx.globalAlpha=alpha*.12;ctx.fill()}}else if(v.type==="slashArc"){const s=ws(v.x,v.y);ctx.translate(s.x,s.y);ctx.rotate(v.a);ctx.lineWidth=v.width||4;ctx.beginPath();ctx.arc(0,0,v.r,-1.05,1.05);ctx.stroke();ctx.globalAlpha=alpha*.28;ctx.lineWidth=Math.max(2,(v.width||4)*.45);ctx.beginPath();ctx.arc(-4,0,v.r*.7,-1,1);ctx.stroke()}else if(v.type==="fallingSword"){const s=ws(v.x,v.y),fall=(1-alpha)*95;ctx.translate(s.x,s.y-95+fall);ctx.rotate(Math.PI/2);ctx.lineWidth=v.width||5;ctx.beginPath();ctx.moveTo(-24,0);ctx.lineTo(18,0);ctx.stroke();ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(25,0);ctx.lineTo(14,-7);ctx.lineTo(14,7);ctx.closePath();ctx.fill()}else if(v.type==="text"){const s=ws(v.x,v.y);ctx.font="bold 13px system-ui";ctx.textAlign="center";ctx.fillText(v.text||"!",s.x,s.y-(1-alpha)*22)}else if(v.type==="spearAura"){const s=ws(v.x,v.y);ctx.translate(s.x,s.y);ctx.rotate(v.a);ctx.globalAlpha=alpha*.22;ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(0,-(v.width||25));ctx.lineTo(v.r,0);ctx.lineTo(0,(v.width||25));ctx.closePath();ctx.fill();ctx.globalAlpha=alpha;ctx.strokeStyle=col;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(v.r,0);ctx.stroke()}ctx.restore()}}
function drawOrbit(){const lv=player.arts.taiji||0;if(!lv)return;const n=taijiCount(lv),rad=taijiRadius(lv),size=taijiBladeSize(lv);ctx.strokeStyle=`rgba(151,209,210,${.10+lv*.025})`;ctx.lineWidth=1+lv*.35;ctx.beginPath();ctx.arc(W/2,H/2,rad,0,Math.PI*2);ctx.stroke();if(lv>=4){ctx.globalAlpha=.28;ctx.beginPath();ctx.arc(W/2,H/2,rad*.58,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}for(let i=0;i<n;i++){const a=elapsed*(2.15+lv*.11)+i*Math.PI*2/n,x=W/2+Math.cos(a)*rad,y=H/2+Math.sin(a)*rad;ctx.save();ctx.translate(x,y);ctx.rotate(a+Math.PI/2);ctx.fillStyle=i%2&&lv>=5?"#eefcff":C.sword;ctx.shadowColor=C.sword;ctx.shadowBlur=lv*1.5;ctx.beginPath();ctx.moveTo(0,-size*1.35);ctx.lineTo(size*.38,size*.75);ctx.lineTo(0,size*1.18);ctx.lineTo(-size*.38,size*.75);ctx.closePath();ctx.fill();ctx.restore()}}
