function drawBossArrows(){for(const e of enemies.filter(x=>!x.dead&&(x.type==="boss"||x.type==="midboss"))){const s=ws(e.x,e.y),margin=55;if(s.x>margin&&s.x<W-margin&&s.y>margin&&s.y<H-margin)continue;const dx=s.x-W/2,dy=s.y-H/2,a=Math.atan2(dy,dx),rx=W/2-margin,ry=H/2-margin,t=Math.min(rx/Math.max(1,Math.abs(Math.cos(a))),ry/Math.max(1,Math.abs(Math.sin(a)))),x=W/2+Math.cos(a)*t,y=H/2+Math.sin(a)*t;ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle=e.type==="boss"?"#ff6e66":"#f0c466";ctx.beginPath();ctx.moveTo(16,0);ctx.lineTo(-9,-10);ctx.lineTo(-5,0);ctx.lineTo(-9,10);ctx.closePath();ctx.fill();ctx.strokeStyle="#1b120e";ctx.stroke();ctx.rotate(-a);ctx.fillStyle="#fff3c9";ctx.font="bold 10px system-ui";ctx.textAlign="center";ctx.fillText(e.type==="boss"?"혈마":e.bossName,0,24);ctx.restore()}}
