function checkAchievements(){ensureV6Account();let changed=false;for(const a of achievementDefs){if(account.achievements[a.id])continue;if(a.value()>=a.goal){account.achievements[a.id]=true;account.gold+=a.reward;changed=true;showMessage(`업적 달성 · ${a.name} (+${a.reward} 금자)`,2.5)}}if(changed)saveAccountData()}
function renderAchievements(){ensureV6Account();checkAchievements();ui.achievementList.innerHTML=achievementDefs.map(a=>{const v=Math.min(a.goal,a.value()),done=!!account.achievements[a.id];return`<div class="collection-card ${done?"unlocked":""}"><b>${done?"✓ ":""}${a.name}</b><p>${a.desc}<br>보상 ${a.reward} 금자</p><div class="achievement-progress"><span style="width:${v/a.goal*100}%"></span></div><p>${v}/${a.goal}</p></div>`}).join("")}
function renderSkins(){ensureV6Account();const wid=selectedWeapon||"sword";ui.skinList.innerHTML=Object.entries(skinDefs).map(([id,sk])=>{const unlocked=!!account.skinsUnlocked[id],selected=currentSkin(wid)===id;return`<div class="collection-card ${unlocked?"unlocked":""}"><b>${selected?"● ":""}${sk.name}</b><p>${characterDefs[wid].name} · ${sk.desc}<br>${unlocked?"보유 중":sk.cost+" 금자"}</p><button data-skin="${id}">${selected?"장착 중":unlocked?"장착":sk.cost+" 금자로 해금"}</button></div>`}).join("");ui.skinList.querySelectorAll("[data-skin]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.skin,sk=skinDefs[id];if(!account.skinsUnlocked[id]){if(account.gold<sk.cost){showMessage("금자가 부족하다",1);return}account.gold-=sk.cost;account.skinsUnlocked[id]=true}account.selectedSkins[wid]=id;saveAccountData();renderSkins();renderCharacterPreview()}))}
function renderRecords(){ensureV6Account();ui.recordContent.innerHTML=`<div class="stat-grid"><div class="stat"><b>${account.stats.runs}</b><span>총 원정</span></div><div class="stat"><b>${account.stats.clears}</b><span>클리어</span></div><div class="stat"><b>${account.stats.kills}</b><span>누적 격파</span></div><div class="stat"><b>${account.stats.perfectDodges}</b><span>정밀 회피</span></div><div class="stat"><b>${Object.keys(account.stats.paths).length}/8</b><span>무기군 경험</span></div><div class="stat"><b>${difficultyDefs[Object.keys(difficultyDefs)[Math.max(0,account.stats.bestDifficulty-1)]]?.name||"-"}</b><span>최고 클리어</span></div></div><h3>보유 자산</h3><div class="stat-grid"><div class="stat"><b>${Math.floor(account.gold)}</b><span>금자</span></div><div class="stat"><b>${totalOres()}</b><span>광석</span></div><div class="stat"><b>${account.weapons.length}</b><span>제작 무기</span></div></div>`}
function loadSettingsUI(){ensureV6Account();$("qualitySelect").value=account.settings.quality;$("fpsSelect").value=String(account.settings.fps);$("shakeSelect").value=String(account.settings.shake);$("damageNumbers").checked=!!account.settings.damageNumbers}
