const baseRenderPause=renderPause;renderPause=function(){baseRenderPause();const extra=`<h3>절기·진화</h3><div class="stat-grid"><div class="stat"><b>${Math.floor(player.ultimate)}%</b><span>절기 게이지</span></div><div class="stat"><b>${player.metrics.perfectDodges||0}</b><span>정밀 회피</span></div><div class="stat"><b>${player.shield||0}</b><span>호신강기</span></div></div>${player.evolutions[selectedWeapon]?`<div class="unlock-banner evolution-mark">진화 무공 · ${player.evolutions[selectedWeapon]}</div>`:""}`;ui.pauseContent.insertAdjacentHTML("afterbegin",extra)};
