const baseRenderWeaponInventory=renderWeaponInventory;renderWeaponInventory=function(){ui.weaponInventory.innerHTML=account.weapons.length?account.weapons.slice().reverse().map(item=>{const gd=gradeDefs.find(g=>g.id===item.grade),eq=account.equipped[item.weapon]===item.id,lvl=item.level||0;return`<div class="weapon-item ${eq?"equipped":""}"><strong><span class="rarity-${item.grade}">${gd.name} ${item.name} +${lvl}</span><span>${item.damageMul.toFixed(2)}x</span></strong><p>${weaponDefs[item.weapon].name} · ${item.abilityName}: ${item.abilityDesc}<br>강화 비용 ${70+lvl*45} 금자 · 재련 비용 ${120+(item.rerolls||0)*60} 금자</p><div class="weapon-actions"><button data-equip="${item.id}">${eq?"장착 중":"장착"}</button><button data-up="${item.id}">강화</button><button data-reroll="${item.id}">재련</button><button data-break="${item.id}">분해</button></div></div>`}).join(""): '<p class="desc">아직 제작한 무기가 없다.</p>';
 ui.weaponInventory.querySelectorAll("[data-equip]").forEach(b=>b.addEventListener("click",()=>{const item=account.weapons.find(x=>x.id===b.dataset.equip);account.equipped[item.weapon]=item.id;saveAccountData();renderWeaponInventory()}));
 ui.weaponInventory.querySelectorAll("[data-up]").forEach(b=>b.addEventListener("click",()=>{const item=account.weapons.find(x=>x.id===b.dataset.up),cost=70+(item.level||0)*45;if(account.gold<cost){showMessage("금자가 부족하다",1);return}account.gold-=cost;item.level=(item.level||0)+1;item.damageMul*=1.035+(item.level%5===0?.025:0);saveAccountData();renderWeaponInventory()}));
 ui.weaponInventory.querySelectorAll("[data-reroll]").forEach(b=>b.addEventListener("click",()=>{const item=account.weapons.find(x=>x.id===b.dataset.reroll),cost=120+(item.rerolls||0)*60;if(account.gold<cost){showMessage("금자가 부족하다",1);return}account.gold-=cost;const types=Object.keys(oreTypes);item.ability=types[Math.floor(Math.random()*types.length)];item.abilityName=oreTypes[item.ability].ability;item.abilityDesc=oreTypes[item.ability].desc;item.rerolls=(item.rerolls||0)+1;saveAccountData();renderWeaponInventory()}));
 ui.weaponInventory.querySelectorAll("[data-break]").forEach(b=>b.addEventListener("click",()=>{const i=account.weapons.findIndex(x=>x.id===b.dataset.break),item=account.weapons[i];if(i<0)return;account.gold+=35+gradeIndex(item.grade)*45+(item.level||0)*20;if(account.equipped[item.weapon]===item.id)delete account.equipped[item.weapon];account.weapons.splice(i,1);saveAccountData();refreshForge()}));checkAchievements()};

